<?php if(!isset($admin,$view,$key)||$view!=='voice'||$key==='new'){http_response_code(404);exit;}
$routing=(new pbx_trunk_routes)->snapshot($key);$routeConfig=$routing['config']; ?>
<section class="trunk-incoming" id="incoming-calls"><h3>Incoming Calls</h3><p class="setup-hint">Incoming routing <?= $e(pbx_trunk_routes::VERSION) ?> · Change where each number goes below. Changes apply to new calls.</p>
<?php if(!$routing['rules']): ?><p>No incoming numbers are set up for this trunk yet.</p><a class="setup-button" href="?view=incoming&amp;edit=new">Add Incoming Number</a><?php endif; ?>
<?php foreach($routing['rules'] as $entry):$rule=$entry['rule'];$callback=$entry['callback'];$activeCallback=$callback&&!empty($callback['enabled']);$routeId=$rule['rule_id']; ?>
<details class="trunk-incoming-rule" open><summary><strong><?= $e($rule['number']?:'Main number fallback') ?></strong> · <?= $e($rule['name']??'') ?></summary>
<p><strong><?= empty($rule['enabled'])||empty($row['enabled'])?'Saved destination (incoming is off)':'Routes now to' ?>:</strong> <?= $e($entry['current']['label']) ?><?php if(!$activeCallback): ?> · <?= $e(['office'=>'Open-hours route','outside'=>'Closed-hours route','holiday'=>'Holiday route'][$entry['current']['slot']]??'') ?><?php endif; ?></p>
<p class="setup-hint">This is the first destination. Its own availability, hours and forwarding still apply.</p>
<form method="post" class="setup-form" action="?view=voice&amp;edit=<?= $e($key) ?>#incoming-calls"><?php $csrf(); ?><input type="hidden" name="action" value="save_trunk_incoming"><input type="hidden" name="incoming_rule" value="<?= $e($routeId) ?>"><input type="hidden" name="route_revision" value="<?= $e($entry['revision']) ?>">
<?php $routeChoices=['keep'=>'Keep · '.pbx_trunk_routes::label($rule['office'],$routeConfig)];foreach($admin->destinations($routeConfig) as $value=>$unused){[$kind,$n]=explode(':',$value,2);$routeChoices[$value]=pbx_trunk_routes::label(['type'=>$kind,'number'=>$n],$routeConfig);}if($callback)$routeChoices['CallMeBack:'.$callback['service_uuid']]='Call Me Back · '.$callback['name']; ?>
<div class="setup-fields"><?php $select('office','Route Calls To',$routeChoices,$activeCallback?'CallMeBack:'.$callback['service_uuid']:'keep','data-trunk-route'); ?><div data-external><?php $input('office_external','External Number',$rule['office']['external']??'','tel'); ?></div></div>
<p data-callback-info <?= $activeCallback?'':'hidden' ?>>Call Me Back answers this number at all times. Its existing accounts, calling permissions and minute limits apply. Your normal destinations below are kept for when you switch back.</p>
<?php if(!$callback): ?><p><a href="?view=call_me_back&amp;service=new">Set up Call Me Back</a> for this incoming number to add it to this list.</p><?php else: ?><p>Call Me Back: <?= $e($callback['prompt_state']==='ready'?'Greeting ready':'Greeting not ready — prepare it before enabling') ?> · <a href="?view=call_me_back&amp;service=<?= $e($callback['service_uuid']) ?>">Manage service and accounts</a></p><?php endif; ?>
<details data-normal-routing><summary>Office Hours &amp; Holiday Routes</summary><div class="setup-fields"><?php $select('office_department','Office Hours Department',[''=>'Use Destination Department']+array_map($departmentName,array_column($routeConfig['departments'],'name','number')),$rule['office_department']??'');foreach(['outside'=>'When Office Is Closed','holiday'=>'On a Holiday'] as $slot=>$title){$choices=['keep'=>'Keep · '.pbx_trunk_routes::label($rule[$slot]??['type'=>'None'],$routeConfig)];foreach($admin->destinations($routeConfig) as $value=>$unused){[$kind,$n]=explode(':',$value,2);$choices[$value]=pbx_trunk_routes::label(['type'=>$kind,'number'=>$n],$routeConfig);}$select($slot,$title,$choices,'keep','data-destination');echo '<div data-external>';$input($slot.'_external','External Number',$rule[$slot]['external']??'','tel');echo '</div>';} ?></div><?php $check('use_outside','Use Office Hours',$rule['use_outside']??false);$check('use_holiday','Use Holiday Destination',$rule['use_holiday']??false); ?></details>
<?php if($callback):$check('confirm_callback','I confirm switching this number to or from Call Me Back'); ?><p class="setup-hint">Confirmation is required only when Call Me Back is switched on or off.</p><?php endif; ?><p class="setup-hint">Saving a route does not change the trunk connection or enable an incoming number.</p>
<div class="setup-actions"><button type="submit" class="setup-button primary">Save Incoming Route</button><a class="setup-button" href="?view=incoming&amp;edit=<?= $e($routeId) ?>">Number Settings</a></div>
</form></details><?php endforeach; ?></section>
